"""English and Urdu teaching copy for the ISP CRM manual."""
PAGES = []


def add(title, urdu, steps=(), image=None, note=None, flow=None, table=None):
    PAGES.append(dict(title=title, urdu=urdu, steps=steps, image=image, note=note, flow=flow, table=table))


add('Start here: your first day', 'یہاں سے شروع کریں: پہلا دن', [
('This guide teaches staff how to use the CRM, then explains the separate customer portal. Read pages 3–7 first; follow the task pages when you need them.', 'اس کتاب میں پہلے عملے کے لیے سی آر ایم کا استعمال اور پھر صارف کے الگ پورٹل کا طریقہ بتایا گیا ہے۔ پہلے صفحات ۳ تا ۷ پڑھیں، پھر ضرورت کے مطابق متعلقہ کام دیکھیں۔'),
('The English words in bold match buttons on screen. Urdu explains what to do. Pictures show fictional training records; enter your own correct details.', 'موٹے انگریزی الفاظ سکرین کے بٹنوں کے نام ہیں۔ اردو میں کام کرنے کا طریقہ ہے۔ تصویروں میں فرضی تربیتی ریکارڈ ہیں؛ اصل کام میں درست معلومات لکھیں۔'),
('Your account decides which menus you see. If a button is missing, ask the administrator to check your role. A customer login is different from a staff login.', 'آپ کے اکاؤنٹ کے اختیار کے مطابق مینو نظر آئیں گے۔ بٹن نظر نہ آئے تو منتظم سے اپنا کردار چیک کروائیں۔ صارف کا لاگ اِن، عملے کے لاگ اِن سے الگ ہے۔')], note=('All amounts are in PKR. Dates use year-month-day; billing months use year-month. Example: 2026-10-21 and 2026-10.', 'تمام رقم پاکستانی روپے میں ہے۔ تاریخ میں سال، مہینہ، دن اور بل کے مہینے میں سال اور مہینہ لکھیں۔ مثال: 2026-10-21 اور 2026-10۔'))

add('The system in one easy picture', 'ایک آسان خاکے میں پورا نظام', [
('Register the customer, choose a package, and save the installation location. Open the profile whenever you need the customer’s complete record.', 'صارف درج کریں، پیکیج منتخب کریں اور تنصیب کی جگہ محفوظ کریں۔ صارف کا مکمل ریکارڈ دیکھنے کے لیے اس کا پروفائل کھولیں۔'),
('Bills show what is charged. Payments and receipts show money actually received. Tickets track work; stock movements track equipment.', 'بل میں واجب الادا رقم ہوتی ہے۔ ادائیگی اور رسید میں واقعی وصول شدہ رقم ہوتی ہے۔ ٹکٹ سے کام اور سٹاک کی نقل و حرکت سے سامان کا حساب رکھا جاتا ہے۔'),
('At the end of the day, check collections, open tickets, equipment returns and expenses; then sign out.', 'دن کے آخر میں وصولیاں، کھلے ٹکٹ، واپس آیا ہوا سامان اور اخراجات چیک کریں، پھر سائن آؤٹ کریں۔')], flow='flowchart TD\n A[Sign in] --> B[Find or register customer]\n B --> C[Customer profile]\n C --> D[Monthly bill]\n D --> E[Receive money and save receipt]\n E --> F[Eligible recharge renews CRM expiry]\n C --> G[Ticket: assign and complete work]\n C --> H[Issue equipment and record charges]\n H --> I[Return recoverable equipment when required]\n F & G & I --> J[Review reports and sign out]', note=('Simple journey: login → customer → bill/work/equipment → payment → review.', 'آسان ترتیب: لاگ اِن ← صارف ← بل، کام یا سامان ← ادائیگی ← روزانہ جائزہ۔'))

add('Open the portal and sign in', 'پورٹل کھولیں اور سائن اِن کریں', [
('On the CRM computer, start the application using start_crm.cmd or python ispcrm.py. Keep it running and open http://localhost:3000 in your browser.', 'سی آر ایم والے کمپیوٹر پر start_crm.cmd یا python ispcrm.py سے پروگرام چلائیں۔ اسے کھلا رکھیں اور براؤزر میں http://localhost:3000 کھولیں۔'),
('Enter the Username and Password supplied by your administrator. Select Sign in. Show reveals the password while you check it; hide it again afterward.', 'منتظم کا دیا ہوا Username اور Password لکھیں۔ Sign in دبائیں۔ پاس ورڈ چیک کرنے کے لیے Show استعمال کریں اور پھر دوبارہ چھپا دیں۔'),
('If this is the first-ever installation, the owner creates the first administrator. Ordinary staff should use their assigned accounts. There is no default password.', 'بالکل نئی تنصیب میں مالک پہلا منتظم اکاؤنٹ بناتا ہے۔ عام عملہ اپنے مقرر کردہ اکاؤنٹ استعمال کرے۔ پہلے سے کوئی طے شدہ پاس ورڈ نہیں ہے۔')], image='01-login', note=('localhost works on the computer running this CRM. For another device, use only an address configured by your administrator.', 'localhost اسی کمپیوٹر پر کام کرتا ہے جہاں سی آر ایم چل رہا ہو۔ دوسرے آلے پر صرف منتظم کا ترتیب دیا ہوا پتہ استعمال کریں۔'))

add('Owner setup and team access', 'مالک کی ابتدائی ترتیب اور عملے کی رسائی', [
('Only at first setup: enter Full name, Username and a password of 10–128 characters, then choose Create administrator. Keep the login details safe.', 'صرف پہلی ترتیب میں Full name، Username اور ۱۰ سے ۱۲۸ حروف کا پاس ورڈ لکھ کر Create administrator دبائیں۔ لاگ اِن کی معلومات محفوظ رکھیں۔'),
('Before registering customers, open Settings → Packages & pricing and create your packages. Add inventory categories and employees if your team will use stock and tickets.', 'صارف درج کرنے سے پہلے Settings → Packages & pricing میں پیکیج بنائیں۔ اگر ٹیم سامان اور ٹکٹ استعمال کرے گی تو سامان کی اقسام اور ملازمین بھی درج کریں۔'),
('In Settings → User management, use + Create user. Choose a role and link the correct employee. Give each person their own account; deactivate accounts when access ends.', 'Settings → User management میں + Create user دبائیں۔ کردار منتخب کریں اور درست ملازم سے اکاؤنٹ جوڑیں۔ ہر فرد کا الگ اکاؤنٹ بنائیں؛ ضرورت ختم ہونے پر اسے غیر فعال کریں۔')], image='02-first-admin', note=('Employee designation and Reports to describe the team structure. The user account’s Role controls application permissions.', 'ملازم کا عہدہ اور Reports to عملے کی ساخت بتاتے ہیں۔ پروگرام میں اختیار، صارف اکاؤنٹ کے Role سے ملتا ہے۔'))

add('Who can do what?', 'کون سا فرد کون سا کام کر سکتا ہے؟', table=[
('Administrator','Full access and user accounts.','مکمل اختیار اور صارف اکاؤنٹس کا انتظام۔'),
('Manager','Business operations and settings; no user administration.','کاروباری کام اور ترتیبات؛ لاگ اِن اکاؤنٹس کا انتظام نہیں۔'),
('Accountant','Payments and expenses; view customers and packages.','ادائیگی اور اخراجات؛ صارف اور پیکیج دیکھ سکتا ہے۔'),
('Support','Customers and tickets; view staff and packages.','صارف اور ٹکٹ سنبھالتا ہے؛ عملہ اور پیکیج دیکھ سکتا ہے۔'),
('Technician','Update assigned tickets; view permitted customer/stock records.','اپنے سپرد ٹکٹ اپ ڈیٹ کرتا ہے؛ اجازت والے ریکارڈ دیکھتا ہے۔'),
('Storekeeper','Inventory and stock issues/returns.','سامان، اس کا اجرا اور واپسی سنبھالتا ہے۔'),
('Viewer','Read-only business records.','کاروباری ریکارڈ صرف دیکھ سکتا ہے۔')], note=('Some profile tabs, financial figures and buttons are hidden when your role does not allow them. Ask the administrator if your work needs additional access.', 'اگر آپ کے کردار کو اجازت نہ ہو تو بعض ٹیب، مالی اعداد اور بٹن چھپے ہوتے ہیں۔ مزید اختیار درکار ہو تو منتظم سے رابطہ کریں۔'))

add('Understand the dashboard', 'ڈیش بورڈ کو سمجھیں', [
('Use the left menu to open Customers, Tickets, Inventory, Payments and other permitted sections. On a small screen, open navigation with the menu button.', 'بائیں مینو سے Customers، Tickets، Inventory، Payments اور اجازت والے حصے کھولیں۔ چھوٹی سکرین پر مینو کے بٹن سے راستہ کھولیں۔'),
('Cards summarize customers, bills, collections, expiry alerts, tickets and stock. Read the selected date or month before comparing amounts. Your role may show a simpler home page.', 'کارڈز میں صارف، بل، وصولی، میعاد، ٹکٹ اور سٹاک کا خلاصہ ہے۔ رقم کا موازنہ کرنے سے پہلے منتخب تاریخ یا مہینہ دیکھیں۔ کردار کے مطابق ہوم پیج سادہ بھی ہو سکتا ہے۔'),
('Use the daily/monthly finance sections for the period you want. Collections means money received. Net cash means collections minus paid expenses; it is not profit.', 'مطلوبہ مدت کے لیے روزانہ یا ماہانہ مالی حصہ دیکھیں۔ Collections وصول شدہ رقم ہے۔ Net cash وصولی میں سے ادا شدہ اخراجات نکال کر بنتا ہے؛ یہ منافع نہیں ہے۔')], image='03-dashboard', note=('Expiry alerts help you follow up. An Active label in the CRM does not prove the router connection is active.', 'میعاد کے انتباہ رابطہ کرنے میں مدد دیتے ہیں۔ سی آر ایم میں Active لکھا ہونا روٹر پر انٹرنیٹ چلنے کی تصدیق نہیں ہے۔'))

add('Find the right customer', 'درست صارف تلاش کریں', [
('Open Customers. In the search box, enter a name, username or 9-digit Payment ID. Check the name and phone before opening a record.', 'Customers کھولیں۔ تلاش کے خانے میں نام، یوزرنیم یا ۹ ہندسوں والا Payment ID لکھیں۔ ریکارڈ کھولنے سے پہلے نام اور فون چیک کریں۔'),
('Use Advanced filters for more specific searches such as phone, CNIC, email, account type or status. Use Clear filters if a known customer disappears from the list.', 'مزید مخصوص تلاش کے لیے Advanced filters استعمال کریں، مثلاً فون، شناختی کارڈ، ای میل، قسم یا حالت۔ موجود صارف نظر نہ آئے تو Clear filters دبائیں۔'),
('Choose View profile for the full account. The row’s More menu contains additional permitted actions. Search first to avoid entering the same customer twice.', 'مکمل اکاؤنٹ کے لیے View profile منتخب کریں۔ قطار کے More مینو میں مزید اجازت والے کام ہیں۔ ایک صارف دوبارہ درج کرنے سے بچنے کے لیے پہلے تلاش کریں۔')], image='04-customers', note=('Payment ID is a permanent customer reference. Keep it with payment enquiries; it is different from a receipt number.', 'Payment ID صارف کی مستقل شناخت ہے۔ ادائیگی کی بات کرتے وقت اسے ساتھ رکھیں؛ یہ رسید نمبر سے الگ ہے۔'))

add('Add a new customer', 'نیا صارف درج کریں', [
('Open Customers → + Add customer. Enter name, phone, username, address and customer type. Add email and identity details when available.', 'Customers → + Add customer کھولیں۔ نام، فون، یوزرنیم، پتہ اور صارف کی قسم لکھیں۔ دستیاب ہونے پر ای میل اور شناختی تفصیل شامل کریں۔'),
('Choose a package. Check Monthly fee and Installation charge. Set Joined/Creation date and Expiry date. The normal default expiry is 30 days after creation.', 'پیکیج منتخب کریں۔ Monthly fee اور Installation charge چیک کریں۔ Joined/Creation date اور Expiry date درج کریں۔ عام طور پر ابتدائی میعاد، بننے کی تاریخ سے ۳۰ دن بعد ہوتی ہے۔'),
('Enter both Latitude and Longitude for the installation site, then save. Check the saved profile and generated Payment ID. Saving a customer does not collect money or issue equipment.', 'تنصیب کی جگہ کے Latitude اور Longitude دونوں درج کریں، پھر محفوظ کریں۔ محفوظ پروفائل اور بننے والا Payment ID چیک کریں۔ صرف صارف محفوظ کرنے سے رقم وصول یا سامان جاری نہیں ہوتا۔')], image='05-add-customer', note=('If no package is available, ask the manager to create an active package first. Do not invent location coordinates.', 'اگر پیکیج دستیاب نہ ہو تو پہلے منتظم سے فعال پیکیج بنوائیں۔ جگہ کے فرضی کوآرڈینیٹ نہ لکھیں۔'))

add('Location pins and customer documents', 'جگہ کا پن اور صارف کی دستاویزات', [
('For location, paste the installation latitude and longitude. Use current location only while you are at the customer’s installation site and allow the browser when asked.', 'جگہ کے لیے تنصیب کے درست عرض بلد اور طول بلد لکھیں۔ Use current location صرف صارف کی تنصیب کی جگہ پر استعمال کریں اور براؤزر کی اجازت مانگنے پر اجازت دیں۔'),
('After saving, open View profile → Documents → + Add document. Select a document type, choose the file and upload. Documents may also be attached while creating the customer.', 'محفوظ کرنے کے بعد View profile → Documents → + Add document کھولیں۔ دستاویز کی قسم اور فائل منتخب کرکے اپ لوڈ کریں۔ صارف بناتے وقت بھی دستاویز لگائی جا سکتی ہے۔'),
('Download a saved document from its name or manage it using the available controls. Access is limited to Administrator, Manager and Support.', 'محفوظ دستاویز اس کے نام سے ڈاؤن لوڈ کریں یا موجود بٹنوں سے سنبھالیں۔ یہ حصہ صرف Administrator، Manager اور Support کے لیے ہے۔')], image='06-profile', note=('Files: PDF, JPG/JPEG, PNG or WebP. Maximum 5 files per upload, 5 MB each, 20 MB combined. Both location coordinates are required for a new connection.', 'فائلیں: PDF، JPG/JPEG، PNG یا WebP۔ ایک اپ لوڈ میں زیادہ سے زیادہ ۵ فائلیں، ہر فائل ۵ ایم بی اور کل ۲۰ ایم بی۔ نئے کنکشن کے لیے جگہ کے دونوں کوآرڈینیٹ ضروری ہیں۔'))

add('Use the customer profile', 'صارف کا پروفائل استعمال کریں', [
('Subscriptions shows the package, monthly fee, status and expiry. Use Edit customer or Change package / expiry for an authorized correction.', 'Subscriptions میں پیکیج، ماہانہ فیس، حالت اور میعاد ہیں۔ اجازت ہونے پر درستگی کے لیے Edit customer یا Change package / expiry استعمال کریں۔'),
('Finance shows charges, bills and recharge history. Ledger shows the dated account calculation. Payment history lists confirmed receipts.', 'Finance میں چارجز، بل اور ری چارج کی تاریخ ہے۔ Ledger میں تاریخ کے ساتھ اکاؤنٹ کا حساب ہے۔ Payment history میں تصدیق شدہ رسیدیں ہیں۔'),
('Tickets tracks complaints and work. Hardware details shows issued items. Activity records ticket updates. Some tabs appear only when your role permits them.', 'Tickets میں شکایت اور کام کا ریکارڈ ہے۔ Hardware details میں جاری سامان ہے۔ Activity میں ٹکٹ کی تبدیلیاں ہیں۔ کچھ ٹیب صرف اجازت والے کردار کو نظر آتے ہیں۔')], image='06-profile', note=('Check the customer name and Payment ID before choosing Recharge customer, Issue stock or Terminate account.', 'Recharge customer، Issue stock یا Terminate account دبانے سے پہلے صارف کا نام اور Payment ID چیک کریں۔'))

add('Record a monthly payment / recharge', 'ماہانہ ادائیگی یا ری چارج درج کریں', [
('Open the correct customer and choose Recharge customer. Alternatively open Payments → + Record payment and find the customer using Payment ID.', 'درست صارف کھول کر Recharge customer دبائیں۔ یا Payments → + Record payment کھولیں اور Payment ID سے صارف تلاش کریں۔'),
('Choose MRC - Monthly bill. Check the billing month and amount due. Enter only the amount actually received, payment date, method and reference. Check arrears too; do not rely only on the package fee.', 'MRC - Monthly bill منتخب کریں۔ بل کا مہینہ اور واجب الادا رقم چیک کریں۔ صرف واقعی وصول شدہ رقم، تاریخ، طریقہ اور حوالہ لکھیں۔ پچھلا بقایا بھی دیکھیں؛ صرف پیکیج فیس پر انحصار نہ کریں۔'),
('Select Save confirmed payment once. Read the result, check the receipt and new expiry if activated. If unsure whether it saved, check Payment history before entering another payment.', 'Save confirmed payment ایک بار دبائیں۔ نتیجہ پڑھیں، رسید اور فعال ہونے کی صورت میں نئی میعاد چیک کریں۔ محفوظ ہونے میں شک ہو تو دوبارہ ادائیگی لکھنے سے پہلے Payment history دیکھیں۔')], image='07-recharge', note=('The normal choice is Keep account unchanged until fully paid. Only authorized finance staff may approve Activate now and carry unpaid amount to next bill.', 'عام انتخاب Keep account unchanged until fully paid ہے۔ صرف مجاز مالی عملہ Activate now and carry unpaid amount to next bill کی منظوری دے سکتا ہے۔'))

add('When does a payment renew the account?', 'ادائیگی سے اکاؤنٹ کب ری نیو ہوتا ہے؟', [
('Current-month MRC must cover the monthly subscription plus earlier unpaid MRC bills. Receipts add together. With no arrears, a PKR 2,000 bill and PKR 800 payment leave PKR 1,200 due.', 'موجودہ مہینے کی MRC ادائیگی میں ماہانہ فیس اور پچھلے واجب الادا ماہانہ بل پورے ہونے چاہئیں۔ رسیدیں جمع ہوتی ہیں۔ پرانا بقایا نہ ہو تو ۲,۰۰۰ روپے کے بل میں ۸۰۰ روپے دینے کے بعد ۱,۲۰۰ روپے باقی ہیں۔'),
('A qualifying recharge sets CRM status to Active and adds 30 days from the later of today or the saved expiry. The same billing month renews only once.', 'شرائط پوری ہونے پر سی آر ایم کی حالت Active ہوتی ہے۔ آج یا محفوظ میعاد میں سے جو تاریخ بعد کی ہو، اس سے ۳۰ دن بڑھتے ہیں۔ ایک بل کے مہینے میں صرف ایک بار میعاد بڑھتی ہے۔'),
('Earlier/future-month payments and OTC do not automatically renew. Terminated accounts do not reactivate from a payment. Approved partial activation keeps the unpaid amount due.', 'پچھلے یا آئندہ مہینے کی ادائیگی اور OTC سے خودکار ری نیو نہیں ہوتا۔ Terminated اکاؤنٹ ادائیگی سے دوبارہ فعال نہیں ہوتا۔ منظور شدہ جزوی ادائیگی میں باقی رقم واجب الادا رہتی ہے۔')], flow='flowchart TD\n A[Confirmed payment] --> B{Current-month MRC?}\n B -->|No| C[Save receipt without renewal]\n B -->|Yes| D{Eligible account; not renewed this month?}\n D -->|No| C\n D -->|Yes| E{Full MRC due received?}\n E -->|Yes| F[Activate CRM and extend expiry once]\n E -->|No| G{Finance approves partial activation?}\n G -->|No| C\n G -->|Yes| H[Keep unpaid balance and activate]\n H --> F', note=('An invoice is a bill. A receipt proves a recorded payment. An activation is the CRM renewal decision. These are three different things.', 'انوائس بل ہے۔ رسید درج شدہ ادائیگی کا ثبوت ہے۔ ایکٹیویشن، سی آر ایم میں ری نیو کا فیصلہ ہے۔ یہ تین الگ چیزیں ہیں۔'))

add('Open, print or save a bill', 'بل کھولیں، پرنٹ کریں یا محفوظ کریں', [
('Open Monthly invoices, or the customer profile → Print invoice / Finance → Open / print. In the invoice window choose the required billing month when available.', 'Monthly invoices کھولیں، یا صارف کے پروفائل میں Print invoice / Finance → Open / print استعمال کریں۔ انوائس کی ونڈو میں دستیاب ہو تو مطلوبہ مہینہ منتخب کریں۔'),
('Check name, Payment ID, month, monthly charge, extra services, previous balance and remaining amount. Current active subscriptions receive automatic monthly bills.', 'نام، Payment ID، مہینہ، ماہانہ چارج، اضافی خدمات، پچھلا بقایا اور باقی رقم چیک کریں۔ موجودہ فعال سبسکرپشن کے ماہانہ بل خود بنتے ہیں۔'),
('Choose Print / Save PDF, then select Save as PDF or your printer in the browser. Printing a bill does not record a payment or renew the account.', 'Print / Save PDF دبائیں، پھر براؤزر میں Save as PDF یا پرنٹر منتخب کریں۔ صرف بل پرنٹ کرنے سے ادائیگی درج یا اکاؤنٹ ری نیو نہیں ہوتا۔')], image='08-invoice', note=('Existing subscription snapshots are preserved. Do not create a new payment just to make a bill appear paid; first confirm the money received.', 'محفوظ سبسکرپشن کی اصل تفصیل برقرار رہتی ہے۔ بل کو ادا شدہ دکھانے کے لیے فرضی ادائیگی نہ لکھیں؛ پہلے وصولی کی تصدیق کریں۔'))

add('Find and print a payment receipt', 'ادائیگی کی رسید تلاش اور پرنٹ کریں', [
('Open Payments → Receipt / Print, or select the RCP receipt link in the customer’s Finance / Payment history.', 'Payments → Receipt / Print کھولیں، یا صارف کے Finance / Payment history میں RCP والی رسید کا لنک دبائیں۔'),
('Check the receipt number, Payment ID, amount, payment method, date, billing month and reference. Read the activation message and expiry shown.', 'رسید نمبر، Payment ID، رقم، ادائیگی کا طریقہ، تاریخ، بل کا مہینہ اور حوالہ چیک کریں۔ ایکٹیویشن کا پیغام اور درج میعاد بھی پڑھیں۔'),
('Use Print / Save PDF to print or save. Saved receipts and their payments cannot be edited or deleted. If a mistake is found, tell the administrator and keep the receipt number.', 'Print / Save PDF سے پرنٹ یا محفوظ کریں۔ محفوظ رسید اور اس کی ادائیگی بدلی یا حذف نہیں کی جا سکتی۔ غلطی ملے تو منتظم کو بتائیں اور رسید نمبر ساتھ دیں۔')], image='08-receipt', note=('A receipt preserves details from the time it was saved. Later customer edits do not rewrite the old receipt.', 'رسید میں محفوظ ہونے کے وقت کی معلومات رہتی ہیں۔ بعد میں صارف کی معلومات بدلنے سے پرانی رسید نہیں بدلتی۔'))

add('Installation, services and the ledger', 'تنصیب، اضافی خدمات اور لیجر', [
('MRC pays monthly subscriptions. OTC pays one-time charges such as Installation, Equipment or Service. For installation use Finance → Record installation payment.', 'MRC ماہانہ سبسکرپشن کی ادائیگی ہے۔ OTC ایک بار کے چارجز، مثلاً Installation، Equipment یا Service کے لیے ہے۔ تنصیب کے لیے Finance → Record installation payment استعمال کریں۔'),
('Use + Add service charge to record an extra service. To collect that charge, use its own Record payment button in Finance. This links the receipt to the correct charge.', 'اضافی خدمت درج کرنے کے لیے + Add service charge دبائیں۔ اس کی وصولی کے لیے Finance میں اسی چارج کا Record payment بٹن استعمال کریں، تاکہ رسید درست چارج سے جڑ جائے۔'),
('Open Ledger to understand the full account: Debit adds charges, Credit records payments, and Running balance shows the result. A positive balance is owed; a negative balance is credit.', 'پورا حساب سمجھنے کے لیے Ledger کھولیں۔ Debit چارج بڑھاتا ہے، Credit ادائیگی دکھاتا ہے اور Running balance نتیجہ بتاتا ہے۔ مثبت بیلنس واجب الادا اور منفی بیلنس پیشگی رقم ہے۔')], image='20-ledger', note=('OTC does not pay monthly MRC or activate the subscription. Enter a clear Reference. Keep service and subscription collections separate.', 'OTC ماہانہ MRC کی ادائیگی یا سبسکرپشن ایکٹیویٹ نہیں کرتا۔ واضح Reference لکھیں۔ خدمت اور ماہانہ فیس کی وصولی الگ رکھیں۔'))

add('Add and check inventory', 'سامان درج کریں اور سٹاک دیکھیں', [
('Open Inventory → + Add inventory. Enter item, active category, available quantity, minimum stock, unit cost, selling price and store location.', 'Inventory → + Add inventory کھولیں۔ چیز، فعال قسم، موجود تعداد، کم از کم سٹاک، خرید لاگت، فروخت قیمت اور رکھنے کی جگہ لکھیں۔'),
('Unit cost is your business cost. Selling price is the customer price. Minimum stock helps identify items needing purchase. Check quantities before promising equipment.', 'Unit cost آپ کی کاروباری لاگت ہے۔ Selling price صارف سے لینے والی قیمت ہے۔ Minimum stock سے خریدنے کی ضرورت معلوم ہوتی ہے۔ سامان دینے کا وعدہ کرنے سے پہلے تعداد چیک کریں۔'),
('For actual equipment leaving or returning to the store, use Issue stock or Return stock. For individually labelled devices, use the QR tools.', 'سٹور سے سامان کے واقعی نکلنے یا واپس آنے پر Issue stock یا Return stock استعمال کریں۔ الگ لیبل والے آلے کے لیے QR کے بٹن استعمال کریں۔')], image='10-inventory', note=('Do not change the total quantity to imitate a customer issue or return; use the movement workflow so the history remains correct.', 'صارف کو سامان دینے یا واپس لینے کے لیے کل تعداد بدلنے کے بجائے سامان کی نقل و حرکت والا طریقہ استعمال کریں، تاکہ تاریخ درست رہے۔'))

add('Issue equipment to a customer', 'صارف کو سامان جاری کریں', [
('Open the customer profile → Issue stock. The customer is already selected. Choose the item, responsible employee, quantity and issue date.', 'صارف کا پروفائل → Issue stock کھولیں۔ صارف پہلے سے منتخب ہوگا۔ چیز، ذمہ دار ملازم، تعداد اور جاری کرنے کی تاریخ منتخب کریں۔'),
('Check Unit selling price and Recovery required. Choose Yes for company equipment that must come back; choose No for sold/customer-owned items when appropriate. Scan the correct QR for a tracked device.', 'Unit selling price اور Recovery required چیک کریں۔ کمپنی کا واپس آنے والا سامان ہو تو Yes منتخب کریں؛ فروخت شدہ یا صارف کی ملکیت والے سامان کے لیے مناسب صورت میں No کریں۔ لیبل والے آلے کا درست QR سکین کریں۔'),
('Choose Issue and deduct stock. Check Hardware details afterward. Stock reduces and customer equipment charges are recorded together. Cancelling the form does not issue anything.', 'Issue and deduct stock دبائیں۔ پھر Hardware details چیک کریں۔ سٹاک کی کمی اور صارف کے سامان کا چارج ایک ساتھ محفوظ ہوتے ہیں۔ فارم منسوخ کرنے سے سامان جاری نہیں ہوتا۔')], image='11-issue-stock', note=('Customer issues create charges using quantity × selling price. System/network issues are not customer bills. A QR represents exactly one available device in Good condition.', 'صارف کے سامان کا چارج تعداد × فروخت قیمت سے بنتا ہے۔ System/Network کا اجرا صارف کا بل نہیں ہے۔ ایک QR صرف ایک دستیاب اور Good حالت والے آلے کے لیے ہے۔'))

add('QR labels and stock checking', 'کیو آر لیبل اور سٹاک کی جانچ', [
('In Inventory choose + Register / Receive QR device. Select the item and optional serial/MAC. Label existing stock keeps quantity unchanged; Receive new device adds one.', 'Inventory میں + Register / Receive QR device کھولیں۔ چیز اور دستیاب ہو تو سیریل یا MAC لکھیں۔ موجود سامان کو لیبل کرنے سے تعداد نہیں بدلتی؛ نیا آلہ وصول کرنے سے ایک بڑھتا ہے۔'),
('Use Scan QR / Device history to find the exact device and its movements. Keep one label on each physical device. Damaged or Under repair units cannot be issued until marked Good after inspection.', 'خاص آلے اور اس کی نقل و حرکت کے لیے Scan QR / Device history استعمال کریں۔ ہر اصل آلے پر الگ لیبل رکھیں۔ Damaged یا Under repair آلہ معائنے کے بعد Good ہونے تک جاری نہیں ہو سکتا۔'),
('Use QR stocktake to start a count, scan the devices physically present, review differences and close the count. The stocktake report does not silently change stock quantities.', 'QR stocktake سے گنتی شروع کریں، موجود آلات سکین کریں، فرق دیکھیں اور گنتی بند کریں۔ سٹاک کی گنتی کی رپورٹ خود سے مقدار تبدیل نہیں کرتی۔')], image='10-inventory', note=('Register one device at a time. Receiving a new device and labelling an existing device are different choices; check the mode before saving.', 'ایک وقت میں ایک آلہ درج کریں۔ نیا آلہ وصول کرنا اور موجود آلے کو لیبل کرنا الگ انتخاب ہیں؛ محفوظ کرنے سے پہلے طریقہ چیک کریں۔'))

add('Return equipment correctly', 'سامان درست طریقے سے واپس لیں', [
('Physically receive all units in the saved issue. Open Stock movements (Stock issues) → Return stock, or the customer’s Hardware details → Return stock.', 'محفوظ اجرا میں درج تمام سامان واقعی واپس وصول کریں۔ Stock movements (Stock issues) → Return stock، یا صارف کے Hardware details → Return stock کھولیں۔'),
('Check item, customer and full issue quantity before confirming. The system restores quantity once, preserves the issue history and updates tracked devices.', 'تصدیق سے پہلے چیز، صارف اور اجرا کی پوری تعداد چیک کریں۔ نظام تعداد صرف ایک بار واپس بڑھاتا، اجرا کی تاریخ محفوظ رکھتا اور لیبل والے آلات اپ ڈیٹ کرتا ہے۔'),
('If this completes all recovery-required items, the recovery status and linked tickets update automatically. A physical return does not automatically refund customer charges.', 'اگر واپس آنے والے تمام ضروری سامان کی واپسی مکمل ہو جائے تو ریکوری کی حالت اور متعلقہ ٹکٹ خود اپ ڈیٹ ہوتے ہیں۔ سامان واپس لینے سے صارف کے مالی چارج خود واپس نہیں ہوتے۔')], flow='flowchart TD\n A[Physically receive the full issue quantity] --> B[Find issue and select Return stock]\n B --> C[Confirm item, customer and quantity]\n C --> D[Stock restored once; movement saved]\n D --> E{All recovery-required items returned?}\n E -->|No| F[Keep recovery pending]\n E -->|Yes| G[Complete recovery and resolve linked work]', note=('Issue records cannot be edited or deleted. For a correction, return the original issue and create a correct new one. Partial returns of a single issue are not supported.', 'سامان کے اجرا کا ریکارڈ بدل یا حذف نہیں کیا جا سکتا۔ درستگی کے لیے اصل اجرا واپس کریں اور درست نیا اجرا بنائیں۔ ایک اجرا کی جزوی واپسی دستیاب نہیں ہے۔'))

add('Create a complaint or work ticket', 'شکایت یا کام کا ٹکٹ بنائیں', [
('From a customer choose + Log ticket, or open Tickets → + New ticket. Confirm the customer, write a clear Subject and describe the problem.', 'صارف کے پروفائل سے + Log ticket، یا Tickets → + New ticket کھولیں۔ صارف چیک کریں، واضح Subject لکھیں اور مسئلہ بیان کریں۔'),
('Choose Type, Priority and Assigned to. Select an available employee. Types include installation, slow speed, billing, maintenance and collection.', 'Type، Priority اور Assigned to منتخب کریں۔ دستیاب ملازم چنیں۔ اقسام میں تنصیب، کم رفتار، بل، مرمت اور وصولی شامل ہیں۔'),
('Review the target time and save. Tell the customer the ticket reference. Use Tickets filters to find active, unassigned, urgent or staff-specific work.', 'مقررہ وقت چیک کرکے محفوظ کریں۔ صارف کو ٹکٹ کا حوالہ دیں۔ Tickets کے فلٹر سے کھلے، غیر تفویض شدہ، فوری یا خاص ملازم کے کام تلاش کریں۔')], image='14-new-ticket', note=('TAT means the target time for completing a ticket. The clock runs continuously, including nights and weekends; it does not pause while awaiting the customer.', 'TAT کام مکمل کرنے کا مقررہ دورانیہ ہے۔ وقت رات اور چھٹی کے دن بھی چلتا رہتا ہے؛ صارف کے انتظار میں خود نہیں رکتا۔'))

add('Work on and resolve a ticket', 'ٹکٹ پر کام کریں اور حل درج کریں', [
('Open Tickets, find the ticket and choose Manage. Technicians update only their assigned tickets. Set In progress when starting; use Awaiting customer when you need the customer.', 'Tickets میں متعلقہ ٹکٹ تلاش کرکے Manage دبائیں۔ ٹیکنیشن صرف اپنے سپرد ٹکٹ اپ ڈیٹ کرتا ہے۔ کام شروع ہو تو In progress اور صارف کی ضرورت ہو تو Awaiting customer منتخب کریں۔'),
('Keep useful notes. Before choosing Resolved or Closed, select an employee and enter Resolution notes explaining the work and result.', 'مفید تفصیل لکھیں۔ Resolved یا Closed کرنے سے پہلے ملازم منتخب کریں اور Resolution notes میں کیا گیا کام اور نتیجہ لکھیں۔'),
('Review the activity timeline and target indicator. Tickets are closed instead of deleted. Recovery tickets follow equipment-return/recharge rules and may not allow manual resolution.', 'تبدیلیوں کی تاریخ اور مقررہ وقت کا اشارہ دیکھیں۔ ٹکٹ حذف کرنے کے بجائے بند کیے جاتے ہیں۔ ریکوری ٹکٹ سامان کی واپسی یا ری چارج کے اصول کے مطابق مکمل ہوتے ہیں؛ دستی حل کی اجازت لازمی نہیں۔')], image='13-tickets', note=('Urgent work needs prompt follow-up. Changing status does not stop the TAT clock. Reopening keeps the original clock.', 'فوری کام پر جلد توجہ دیں۔ حالت بدلنے سے TAT کا وقت نہیں رکتا۔ دوبارہ کھولنے پر اصل وقت برقرار رہتا ہے۔'))

add('Close an account and recover devices', 'اکاؤنٹ بند کریں اور آلات واپس لیں', [
('For a confirmed permanent closure, open the correct customer → Terminate account. Enter the reason and optionally choose a recovery employee. Check details before Terminate and open recovery.', 'مستقل بندش کی تصدیق ہونے پر درست صارف → Terminate account کھولیں۔ وجہ لکھیں اور چاہیں تو ریکوری ملازم منتخب کریں۔ Terminate and open recovery سے پہلے تفصیل چیک کریں۔'),
('Open Device recovery (Equipment recovery) → View recovery. If recoverable equipment remains, physically collect it and choose Recover and return to stock for the full issue.', 'Device recovery (Equipment recovery) → View recovery کھولیں۔ واپس آنے والا سامان باقی ہو تو واقعی وصول کریں اور پورے اجرا کے لیے Recover and return to stock دبائیں۔'),
('When every required item is returned, recovery completes. The account remains Terminated until separately reactivated by an authorized user. A payment alone does not reactivate it.', 'تمام ضروری سامان واپس آنے پر ریکوری مکمل ہوتی ہے۔ مجاز فرد کے الگ سے دوبارہ فعال کرنے تک اکاؤنٹ Terminated رہتا ہے۔ صرف ادائیگی اسے دوبارہ فعال نہیں کرتی۔')], image='15-recovery', note=('A customer expired for five or more days can receive an automatic expiry-recovery ticket. That ticket resolves after successful recharge or return of all required equipment.', 'میعاد ختم ہوئے پانچ یا زیادہ دن ہوں تو صارف کا خودکار ریکوری ٹکٹ بن سکتا ہے۔ یہ کامیاب ری چارج یا تمام ضروری سامان واپس آنے پر حل ہوتا ہے۔'))

add('Record expenses and installation costs', 'اخراجات اور تنصیب کی لاگت درج کریں', [
('Open Expenses → + Add expense. Enter title, category, payee, amount and expense date. Select the customer only when the expense belongs to that installation/account.', 'Expenses → + Add expense کھولیں۔ عنوان، قسم، رقم لینے والا، رقم اور خرچ کی تاریخ درج کریں۔ صرف متعلقہ تنصیب یا اکاؤنٹ کا خرچ ہو تو صارف منتخب کریں۔'),
('Choose Pending if unpaid, Paid when actually paid, or Cancelled when no longer valid. Paid needs a Payment date and the correct payment method.', 'ادا نہ ہوا ہو تو Pending، واقعی ادا ہو تو Paid، اور خرچ منسوخ ہو تو Cancelled منتخب کریں۔ Paid کے لیے Payment date اور درست طریقہ لکھیں۔'),
('For a customer’s total setup cost, open Activation costs if permitted. It combines recorded issued inventory business costs with allocated noncancelled expenses.', 'صارف کی کل ابتدائی لاگت کے لیے اجازت ہونے پر Activation costs کھولیں۔ اس میں جاری سامان کی محفوظ کاروباری لاگت اور صارف سے متعلق غیر منسوخ اخراجات جمع ہوتے ہیں۔')], image='16-expenses', note=('Avoid counting the same equipment cost again as an activation expense. Monthly package cost is separate. A selling price is not your business cost.', 'ایک ہی سامان کی لاگت دوبارہ تنصیب کے خرچ میں شامل نہ کریں۔ ماہانہ پیکیج لاگت الگ ہے۔ فروخت قیمت آپ کی خرید لاگت نہیں ہے۔'))

add('Register employees and set up packages', 'ملازمین درج کریں اور پیکیج بنائیں', [
('Open Staff → + Register employee. Enter name, phone, work role, area, availability and relevant employment details. Employee codes are generated automatically.', 'Staff → + Register employee کھولیں۔ نام، فون، کام، علاقہ، دستیابی اور متعلقہ ملازمت کی تفصیل لکھیں۔ ملازم کا کوڈ خود بنتا ہے۔'),
('Use Reports to for the reporting manager. Registration is not a staff login: the administrator creates a separate user account and links the employee when needed.', 'رپورٹنگ افسر کے لیے Reports to استعمال کریں۔ ملازم درج کرنے سے لاگ اِن نہیں بنتا؛ ضرورت پر منتظم الگ صارف اکاؤنٹ بنا کر ملازم سے جوڑتا ہے۔'),
('In Settings, manage Packages & pricing, Inventory categories, Employee designations and Ticket TAT. User management is only for the administrator.', 'Settings میں Packages & pricing، Inventory categories، Employee designations اور Ticket TAT سنبھالیں۔ User management صرف منتظم کے لیے ہے۔')], image='18-settings', note=('Changing a package’s catalog price does not automatically change an existing customer’s agreed monthly fee. Deactivate used packages/categories when deletion is blocked.', 'پیکیج کی فہرستی قیمت بدلنے سے موجود صارف کی طے شدہ ماہانہ فیس خود نہیں بدلتی۔ استعمال شدہ پیکیج یا قسم حذف نہ ہو تو غیر فعال کریں۔'))

add('Read, export and print reports', 'رپورٹ دیکھیں، ایکسپورٹ اور پرنٹ کریں', [
('Open Reports in the left menu and select a report. Common choices include Collection Reports, Expiry Report, Accounts Report, Daily Sales Report and Recharge Report.', 'بائیں مینو میں Reports کھول کر رپورٹ منتخب کریں۔ عام رپورٹس میں Collection Reports، Expiry Report، Accounts Report، Daily Sales Report اور Recharge Report ہیں۔'),
('Set From and To dates; use the report search if needed. Read the note below the report title because each report uses dates and balances differently.', 'From اور To کی تاریخیں منتخب کریں؛ ضرورت ہو تو رپورٹ میں تلاش کریں۔ عنوان کے نیچے نوٹ پڑھیں کیونکہ مختلف رپورٹس میں تاریخ اور بیلنس کا مطلب مختلف ہو سکتا ہے۔'),
('Use Export CSV for a spreadsheet or Print for paper/Save as PDF. Check the date range and filters before sharing. Inventory Reconciliation is available to inventory readers.', 'سپریڈشیٹ کے لیے Export CSV اور کاغذ یا PDF کے لیے Print دبائیں۔ بھیجنے سے پہلے تاریخ کی حد اور فلٹر چیک کریں۔ سامان دیکھنے کی اجازت والے کو Inventory Reconciliation ملتی ہے۔')], image='21-reports', note=('Sales, collections and unpaid balances are different. Sales includes bills raised; collections uses actual payment dates. Read report notes before comparing totals.', 'فروخت، وصولی اور غیر ادا شدہ بیلنس الگ ہیں۔ فروخت میں بنے بل اور وصولی میں اصل ادائیگی کی تاریخ آتی ہے۔ اعداد ملانے سے پہلے رپورٹ کے نوٹ پڑھیں۔'))

add('Customer portal: first login', 'صارف کا پورٹل: پہلی بار لاگ اِن', [
('Staff: open the customer profile → Customer app access to provision/reset separate portal credentials. Give the customer their 9-digit Payment ID and temporary password securely.', 'عملہ: صارف کا پروفائل → Customer app access کھول کر الگ پورٹل کی رسائی بنائیں یا نیا عارضی پاس ورڈ بنائیں۔ صارف کو ۹ ہندسوں والا Payment ID اور عارضی پاس ورڈ محفوظ طریقے سے دیں۔'),
('Customer: on the CRM computer open http://localhost:3000/customer/. On another device, ask your ISP for the configured customer portal link. Enter Payment ID and Password, then Sign in securely.', 'صارف: سی آر ایم والے کمپیوٹر پر http://localhost:3000/customer/ کھولیں۔ دوسرے آلے پر اپنے آئی ایس پی سے ترتیب دیا ہوا لنک لیں۔ Payment ID اور Password لکھ کر Sign in securely دبائیں۔'),
('At first login, replace the temporary password. Enter the current temporary password and choose a new password of 10–128 characters. Then open your account.', 'پہلے لاگ اِن پر عارضی پاس ورڈ بدلیں۔ موجودہ عارضی پاس ورڈ لکھیں اور ۱۰ سے ۱۲۸ حروف کا نیا پاس ورڈ رکھیں۔ پھر اپنا اکاؤنٹ کھولیں۔')], image='19-customer-login', note=('Customer accounts are separate from staff usernames. Ask your ISP for access; a Payment ID alone is not a password.', 'صارف کے اکاؤنٹ عملے کے یوزرنیم سے الگ ہیں۔ رسائی کے لیے آئی ایس پی سے رابطہ کریں؛ صرف Payment ID پاس ورڈ نہیں ہے۔'))

add('Customer portal: everyday use', 'صارف کا پورٹل: روزمرہ استعمال', [
('Overview shows your status, expiry, amount due and internet plan. Bills → View / Print opens a bill. Receipts lists confirmed payments recorded by your ISP.', 'Overview میں حالت، میعاد، واجب الادا رقم اور پیکیج ہیں۔ Bills → View / Print سے بل کھلتا ہے۔ Receipts میں آئی ایس پی کی درج کردہ تصدیق شدہ ادائیگیاں ہیں۔'),
('Read Notifications and use Mark as read. Support shows existing tickets; contact your ISP to open a new support request. Account includes Change password.', 'Notifications پڑھیں اور Mark as read دبائیں۔ Support میں موجود ٹکٹ ہیں؛ نئی شکایت کے لیے آئی ایس پی سے رابطہ کریں۔ Account میں Change password ہے۔'),
('Use your Payment ID when contacting support. Ask the ISP for payment instructions. Sign out when finished, especially on a shared computer.', 'سپورٹ سے بات کرتے وقت Payment ID دیں۔ ادائیگی کی ہدایات آئی ایس پی سے لیں۔ کام ختم ہونے پر، خاص طور پر مشترکہ کمپیوٹر پر، Sign out کریں۔')], image='19-customer-home', note=('The portal displays ISP records. Viewing a bill does not pay it. This version does not itself provide customer self-payment or a new-ticket submission form.', 'پورٹل آئی ایس پی کا محفوظ ریکارڈ دکھاتا ہے۔ بل دیکھنے سے ادائیگی نہیں ہوتی۔ اس ورژن میں صارف کی طرف سے براہ راست ادائیگی یا نیا ٹکٹ جمع کرنے کا فارم نہیں ہے۔'))

add('If something does not work', 'اگر کوئی مسئلہ پیش آئے', table=[
('Page will not open','Make sure the CRM is running. Check the address and ask the administrator to check the database if an error appears.','پروگرام چلتا ہو اور پتہ درست ہو۔ خرابی آئے تو منتظم سے ڈیٹابیس چیک کروائیں۔'),
('Cannot sign in','Check username, password and Caps Lock. Use Forgot password? if configured, or contact the administrator.','یوزرنیم، پاس ورڈ اور کیپس لاک چیک کریں۔ دستیاب ہو تو Forgot password? استعمال کریں، ورنہ منتظم سے رابطہ کریں۔'),
('Menu or button missing','Ask the administrator to check your assigned role.','منتظم سے اپنے مقرر کردہ کردار اور اجازت چیک کروائیں۔'),
('Save rejected','Read the message, correct required fields, and reload if told to. Check existing history before retrying a payment.','پیغام پڑھیں، ضروری خانے درست کریں اور کہا جائے تو صفحہ ری لوڈ کریں۔ ادائیگی دوبارہ لکھنے سے پہلے تاریخ دیکھیں۔'),
('Paid but not renewed','Check MRC/OTC, billing month, remaining arrears, prior renewal and Terminated status.','MRC/OTC، بل کا مہینہ، باقی بقایا، پہلے ری نیو ہونے اور Terminated حالت کو چیک کریں۔'),
('Stock return blocked','Confirm the correct issue and full quantity. Ask the storekeeper/administrator to review.','درست اجرا اور پوری تعداد چیک کریں۔ سٹور کیپر یا منتظم سے جائزہ کروائیں۔')], note=('For a password reset, a linked employee email and configured email service are needed. Use Password in the top bar to change a known staff password; sign in again afterward.', 'بھولا پاس ورڈ بحال کرنے کے لیے ملازم کی منسلک ای میل اور ترتیب شدہ ای میل سروس درکار ہے۔ معلوم پاس ورڈ بدلنے کے لیے اوپر Password دبائیں؛ بعد میں دوبارہ سائن اِن کریں۔'))

add('Daily checklist and simple word guide', 'روزانہ کی فہرست اور آسان اصطلاحات', [
('Morning: check expiry alerts and open tickets. During work: verify the customer, save confirmed receipts, record equipment issues/returns and update tickets.', 'صبح: میعاد کے انتباہ اور کھلے ٹکٹ دیکھیں۔ کام کے دوران: درست صارف چیک کریں، تصدیق شدہ رسیدیں محفوظ کریں، سامان کا اجرا یا واپسی درج کریں اور ٹکٹ اپ ڈیٹ کریں۔'),
('Evening: compare receipts with received money, enter paid/pending expenses, review unresolved work and equipment recovery, then Sign out.', 'شام: رسیدوں کو وصول شدہ رقم سے ملائیں، ادا شدہ یا باقی اخراجات درج کریں، غیر حل شدہ کام اور سامان کی ریکوری دیکھیں، پھر Sign out کریں۔')], table=[
('MRC','Monthly subscription charge/payment.','ماہانہ سبسکرپشن کا چارج یا ادائیگی۔'),
('OTC','One-time installation, equipment or service charge/payment.','تنصیب، سامان یا خدمت کا ایک بار کا چارج یا ادائیگی۔'),
('Invoice / Receipt','Invoice: bill. Receipt: recorded payment proof.','انوائس: بل۔ رسید: درج شدہ ادائیگی کا ثبوت۔'),
('Expiry / Recharge','Expiry: saved end date. Recharge: qualifying CRM renewal.','میعاد: محفوظ آخری تاریخ۔ ری چارج: شرائط کے مطابق سی آر ایم کی تجدید۔'),
('Ledger / TAT','Ledger: account history. TAT: ticket completion target time.','لیجر: اکاؤنٹ کا حساب۔ TAT: ٹکٹ مکمل کرنے کا مقررہ وقت۔')], note=('Need help? Share the customer Payment ID, receipt/ticket reference and exact error message with your administrator. Do not share your password.', 'مدد چاہیے؟ صارف کا Payment ID، رسید یا ٹکٹ نمبر اور خرابی کا پورا پیغام منتظم کو دیں۔ اپنا پاس ورڈ نہ دیں۔'))
